mapper.select:
/* AI 대화방 목록 조회 */ SELECT AI_CNVRS_ROOM_SN , MBR_SN , PET_SN , CNVRS_TTL_ENC , REG_DT FROM AI_CNVRS_ROOM WHERE MBR_SN = #{mbrSn}
AND PET_SN = #{petSn}
ORDER BY REG_DT DESC , AI_CNVRS_ROOM_SN DESC

/* AI 대화방 단건 조회(본인 것만) */
SELECT AI_CNVRS_ROOM_SN
     , MBR_SN
     , PET_SN
     , CNVRS_TTL_ENC
     , REG_DT
  FROM AI_CNVRS_ROOM
 WHERE AI_CNVRS_ROOM_SN = #{aiCnvrsRoomSn}
   AND MBR_SN = #{mbrSn}

/* AI 대화방 잠금 조회(본인 것만) */
SELECT AI_CNVRS_ROOM_SN
     , MBR_SN
     , PET_SN
     , CNVRS_TTL_ENC
     , REG_DT
  FROM AI_CNVRS_ROOM
 WHERE AI_CNVRS_ROOM_SN = #{aiCnvrsRoomSn}
   AND MBR_SN = #{mbrSn}
   FOR UPDATE

/* AI 대화 다음 메시지 순서 조회 */
SELECT COALESCE(MAX(MSG_SEQ), 0) + 1
  FROM AI_CNVRS_MSG
 WHERE AI_CNVRS_ROOM_SN = #{aiCnvrsRoomSn}

mapper.insert:
/* AI 대화방 등록 */
INSERT INTO AI_CNVRS_ROOM
     ( MBR_SN
     , PET_SN
     , CNVRS_TTL_ENC
     , REG_DT )
VALUES
     ( #{mbrSn}
     , #{petSn}
     , #{cnvrsTtlEnc}
     , NOW() )

/* AI 대화 메시지 등록 */
INSERT INTO AI_CNVRS_MSG
     ( AI_CNVRS_ROOM_SN
     , ROLE_CD
     , CNVRS_CN_ENC
     , MSG_SEQ
     , REG_DT
     , CMPTN_YN )
VALUES
     ( #{aiCnvrsRoomSn}
     , #{roleCd}
     , #{cnvrsCnEnc}
     , #{msgSeq}
     , NOW()
     , #{cmptnYn} )

mapper.delete:
/* AI 대화방 삭제(본인 것만, 메시지는 CASCADE) */
DELETE FROM AI_CNVRS_ROOM
 WHERE AI_CNVRS_ROOM_SN = #{aiCnvrsRoomSn}
   AND MBR_SN = #{mbrSn}

